#!/usr/bin/env python3
# luxarch:shared-machine hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
r"""Deny what makes a shared machine's state one agent's by accident: stray writes, fixed names, ports.

FLEET-AGENT-CONDUCT-STANDARD, "Shared machine": a worktree isolates the files git tracks, and
everything else on the machine is shared by every agent of every repo. Seen in three days: fake
`/usr/bin/swift` and `/usr/bin/xcrun` left for every later session, attack fixtures in `/tmp` and
`/root`, one gate log overwritten by another repo's run, every worktree building one
`luxarch:local` tag. PreToolUse(Edit | Write | MultiEdit | NotebookEdit | Bash) denies:

1. A write outside the allowed places. An edit tool's `file_path`/`notebook_path`; in a command,
   an output redirect (`>`, `>>`, `>|`, `&>`, `<>`, written after a word too: `echo hi>/etc/x`;
   not `\>`, nor a comparison in `[[ … ]]`), and the target of `tee`, `cp`, `mv`, `install`, `ln`,
   `mkdir`, `touch`, `truncate`, `sed -i`, `perl -i`, `rsync` (a local destination, and its
   backup, partial and log files), `dd of=`, `curl` (`-o`, `-O` into the current directory, `-D`,
   `-c`, `--trace`, `--stderr`), `wget` (its download, `-o`, `--save-cookies`), `git clone`, `git
   init` (with `--git-dir`/`$GIT_DIR`), `git worktree add|move`, `tar` (extracting, or creating,
   appending to or deleting from an archive), `unzip`, `find -fprint`, `strace`/`ltrace -o`,
   `docker cp`, `flock`'s lock file and `mktemp` (which creates in `$TMPDIR` or `/tmp` unless given
   a directory). A long option may be abbreviated (`--targ`, `--t`), as getopt allows, and an
   option may follow the operands. A relative path is read from the shell's directory, following
   `cd` (undone where a `( … )` subshell ends; a `cd` inside `$(…)` or `bash -c` stays there, and
   such a text is judged from every directory the outer command visits), `git -C`, `env -C`
   and `sudo -D`; `~`, `~user`, `$HOME` and known variables (`${X:-…}`,
   `${X:+…}`, `${X%…}`) are expanded; symlinks are followed before `..` is applied, as the kernel
   does, and a glob is matched against what exists. Wrappers `_cmdtext` does not set aside
   (`setsid`, `ionice`, `chrt`, `taskset`, `unshare`, `runuser`, `fakeroot`, `flock`, `busybox`,
   `coproc`, `strace`, …, and a `sudo`/`env` whose options `_cmdtext` stops in: `sudo -iu root`)
   are opened to the command and command strings (`flock -c`, `runuser -c`) they run; more than
   four deep is denied. The allowed places, each with its reason:
     * the project dir (`CLAUDE_PROJECT_DIR`) and the git toplevel it sits in: the checkout, or
       the issue worktree, the unit works in (never the shell's `cwd`, which a `cd` moves). A worktree nested in the project dir is
       inside it: which worktree is a unit's is not in the event (a subagent's `cwd` is its
       parent's), so a sibling worktree is not told apart.
     * that checkout's own git common dir (its `.git`, or the repo whose worktree registry
       names it): a worktree's git internals live in the main checkout's `.git`.
     * an issue worktree of any repo, `<repo>/.claude/worktrees/<KEY>[-<role>]/`, confirmed
       by that repo's git registry: a unit may work another repo's issue.
     * the session's scratchpad, `/tmp/claude-<uid>/<launch folder>/<session id>/scratchpad/`, the
       `<scratch>` of the standard (subagents share their parent's session id, so theirs too). Any
       session's when the event names none. Not the rest of `/tmp`: that is shared.
     * Claude Code's auto memory, `<config>/projects/<project>/memory/`, and its plan files,
       `<config>/plans/` (`<config>` is `$CLAUDE_CONFIG_DIR`, else `~/.claude`): Claude Code's own
       procedures write them, through the edit tools. Not its settings: those are the owner's.
     * `/dev/null`, `/dev/stdout`, `/dev/stderr`, `/dev/tty` and `/dev/fd/<n>`: streams, not files.
   Reads are never judged. Not seen: a path computed at run time (`$(…)`, a variable the command
   does not set, a `for` loop's variable, `cd` into one, `CDPATH`, `~-`), a symlink the same
   command creates before writing through it, what a program writes on its own (`python3 -c`, a
   script, a build, `parallel`), a bind mount docker creates, and what `_cmdtext` does not open (a
   script run by `source`/`.`, a `find -exec` word built around `{}`, `env -S'…'` attached).
2. A fixed docker name or tag: `docker run|create --name X`, `docker compose run --name X`,
   `docker build|buildx build|image build -t|--tag X`, `docker tag … X`, `docker compose
   -p|--project-name X` (or `COMPOSE_PROJECT_NAME=X`), `docker network|volume create X`, where X
   names no issue key: in an issue worktree (`.claude/worktrees/<KEY>`) THAT key, in any case
   (`postgres-16` is not keyed there); elsewhere any `[A-Za-z][A-Za-z0-9]+-[0-9]+`, and `docker rename … X`, `docker commit … X`. `docker run --rm` with no `--name` passes,
   and so does a name holding an expansion the command does not set (`web-$$`). podman likewise.
3. A fixed host port: `docker run|create|compose run -p|--publish H:C` with a numeric host port.
   `-p 127.0.0.1::C`, `-p C`, host port 0 (the kernel picks one) and `-P` pass.

A command `make` runs is out of scope: the emitted blocks own their names, ports and paths (a
redirect of make's output is the shell's, and is judged). Commands are read through `_cmdtext`:
argv as the shell will run it (wrappers such as `sudo`/`env`/`timeout` set aside), with what the
shell runs from inside a command (`bash -c`, `$(…)`, `eval`, `find -exec`, a heredoc or
here-string fed to a shell) judged too; quoted data and heredoc bodies are not commands. A tool
call this hook cannot read is denied. Its helpers beside it: `_shared_machine_argv` (the paths a
program's argv writes) and `_shared_machine_docker` (names, tags and ports).
"""

from __future__ import annotations

import glob
import os
import pwd
import re
import shlex
import subprocess
import sys
from pathlib import Path
from typing import NamedTuple

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (  # sibling helper, loaded by path
    SimpleCommand,
    argv_bodies,
    executable_texts,
    expand,
    guarded,
    load_event,
    redirects,
    segments,
    shell_split,
    simple_commands,
    text_field,
    tool_input,
)
from _shared_machine_argv import argv_writes, canon  # sibling helper, loaded by path
from _shared_machine_docker import (  # sibling helper, loaded by path
    docker_problems,
    set_unit,
)

_EDIT_FIELD = {
    "Edit": "file_path",
    "Write": "file_path",
    "MultiEdit": "file_path",
    "NotebookEdit": "notebook_path",
}
_OUTPUT_OPS = {">", ">>", ">|", ">&", "<>"}
_ISSUE_WORKTREE = re.compile(
    r"^(/.+?)/\.claude/worktrees/[A-Za-z][A-Za-z0-9]*-\d+(?:-[A-Za-z0-9._]+)*(?:/|\Z)"
)  # `<KEY>` or `<KEY>-<role>` (`AB-12-verify`)
_STREAMS = re.compile(r"^/dev/(?:null|stdout|stderr|tty|fd/\d+)$")
# An expansion the command does not set: it stands for one unknown path segment.
_UNKNOWN = re.compile(r"\$\([^)]*\)?|`[^`]*`?|\$\{[^}]*\}?|\$[A-Za-z_]\w*|\$.")
_PLACEHOLDER = "\x00"
_GIT_ERRORS = (OSError, subprocess.SubprocessError)
_NAMED = ("/usr", "/bin", "/etc", "/opt", "/root")


def _under(path: str, root: str) -> bool:
    return path == root or path.startswith(root.rstrip("/") + "/")


class Where:
    """Where this call may write: worked out once, lazily (git runs only when a path is judged)."""

    def __init__(self, ev: dict[str, object]) -> None:
        self.cwd = text_field(ev, "cwd") or os.getcwd()
        self.session = (
            text_field(ev, "session_id")
            or os.environ.get("CLAUDE_SESSION_ID", "")
            or os.environ.get("CLAUDE_CODE_SESSION_ID", "")
        )
        self.home = os.environ.get("HOME") or str(Path.home())
        self._roots: list[str] | None = None
        self._worktrees: dict[str, bool] = {}

    def roots(self) -> list[str]:
        if self._roots is None:
            roots = []
            project = os.environ.get("CLAUDE_PROJECT_DIR", "")
            if project:
                roots.append(project)
            # The checkout is the PROJECT's, never the shell's: a `cd` into another repo (not a
            # write) would otherwise make that repo's checkout, or a `.git` planted in scratch,
            # an allowed root. Another repo's issue worktree is `_issue_worktree`'s question.
            top, common = self._git(project or self.cwd)
            roots += [p for p in (top, common) if p]
            if not roots and self.cwd not in ("/", self.home):
                roots.append(self.cwd)
            # A root that holds a shared place is no root: one config write (`core.worktree /`,
            # a `.git` file whose commondir is `/`) would otherwise allow every path.
            self._roots = [
                r
                for r in (os.path.realpath(x) for x in roots)
                if not self._too_broad(r)
            ]
        return self._roots

    def _too_broad(self, root: str) -> bool:
        shared = ("/", "/tmp", "/var", "/var/tmp", *_NAMED, os.path.realpath(self.home))
        return any(_under(os.path.realpath(s), root) for s in shared if s)

    def _git(self, start: str) -> tuple[str, str]:
        """The checkout `start` is in, and its git common dir.

        The toplevel is the nearest directory above `start` holding `.git`, found on disk: git's
        `--show-toplevel` honours `core.worktree`, which a config write in the project can set
        to `/`. The common dir counts only when it is the checkout's own: its `.git` directory,
        or, for a linked worktree, the repo whose registry entry (`<common>/worktrees/<name>/
        gitdir`) names `<top>/.git`. A `.git` file is otherwise free to name any repo's."""
        top = ""
        d = os.path.realpath(start)
        while True:
            if os.path.lexists(os.path.join(d, ".git")):
                top = d
                break
            parent = os.path.dirname(d)
            if parent == d:
                return "", ""
            d = parent
        lines = Where._rev_parse(top, "--absolute-git-dir", "--git-common-dir")
        if not lines:
            return top, ""
        gdir = os.path.realpath(lines[0])
        common = os.path.realpath(os.path.join(top, lines[1]))
        own = os.path.realpath(os.path.join(top, ".git"))
        if gdir == common:
            return (
                top,
                common if common == own else "",
            )  # a main checkout's own `.git` dir
        if os.path.dirname(gdir) != os.path.join(common, "worktrees"):
            return top, ""
        try:
            back = Path(gdir, "gitdir").read_text(encoding="utf-8").strip()
        except OSError:
            return top, ""
        linked = os.path.realpath(os.path.join(gdir, back)) == own
        return top, common if linked else ""

    def scratch(self) -> str:
        session = re.escape(self.session) if self.session else "[^/]+"
        return (
            rf"^{re.escape(os.path.realpath('/tmp'))}/claude-{os.getuid()}/[^/]+/{session}"
            r"/scratchpad(?:/|\Z)"
        )

    def scratch_hint(self) -> str:
        if self.session:
            for d in sorted(
                Path("/tmp").glob(f"claude-{os.getuid()}/*/{self.session}/scratchpad")
            ):
                return str(d)
        return f"/tmp/claude-{os.getuid()}/<launch folder>/<session id>/scratchpad"

    def allowed(self, path: str) -> bool:
        if _STREAMS.match(os.path.normpath(path)):
            return True
        real = os.path.realpath(path)
        if re.match(self.scratch(), real):
            return True
        config = os.path.realpath(
            os.environ.get("CLAUDE_CONFIG_DIR") or os.path.join(self.home, ".claude")
        )
        if re.match(
            rf"^{re.escape(config)}/(?:projects/[^/]+/memory|plans)(?:/|\Z)", real
        ):
            return True
        return any(_under(real, r) for r in self.roots()) or self._issue_worktree(real)

    def _issue_worktree(self, real: str) -> bool:
        """`real` lies in a fleet issue worktree, `<repo>/.claude/worktrees/<KEY>`, of any repo.

        An agent's unit may live in another repo than the session's (a guard maintainer works
        luxaudit's issue from a luxarch session), so the session's project is not the only place
        that is the unit's. The path's text only nominates the worktree; git decides, and git is
        asked about the REPO, not about files inside the candidate (which a write the hook cannot
        see could forge):
          * `<repo>` is a main checkout: its toplevel is itself, and its git dir is its common dir
            (a `.git` FILE, as `--separate-git-dir` and submodules write, is followed by git);
          * an existing `<root>` is a linked worktree of THAT repo: git's own registry entry
            `<common>/worktrees/<name>/gitdir` names `<root>/.git`, and `<root>`'s git dir is that
            entry;
          * a `<root>` that does not exist yet is the place `git worktree add` creates it, so a
            write of `<root>` itself is allowed (not of a file under it); once it exists it must
            pass the check above.
        A made-up `.claude/worktrees/X-1` directory, a forged `.git` file in one, the repo's main
        checkout, and a symlinked `.claude` or worktree (the resolved path loses the shape; this
        fails closed) are not one."""
        m = _ISSUE_WORKTREE.match(real)
        if not m:
            return False
        repo, root = m.group(1), m.group(0).rstrip("/")
        if not os.path.lexists(root) and real != root:
            # Only the worktree itself is created before it exists (`git worktree add <root>`);
            # a file planted under a future worktree squats it for the unit that makes it.
            return False
        if root not in self._worktrees:
            self._worktrees[root] = self._is_issue_worktree(repo, root)
        return self._worktrees[root]

    @staticmethod
    def _rev_parse(where: str, *args: str) -> list[str]:
        try:
            r = subprocess.run(
                ["git", "-C", where, "rev-parse", *args],
                capture_output=True,
                text=True,
                timeout=4,
                check=False,
                env={k: v for k, v in os.environ.items() if not k.startswith("GIT_")},
            )
        except _GIT_ERRORS:
            return []
        lines = r.stdout.splitlines() if r.returncode == 0 else []
        return lines if len(lines) == len(args) else []

    def _is_issue_worktree(self, repo: str, root: str) -> bool:
        main = self._rev_parse(
            repo, "--show-toplevel", "--absolute-git-dir", "--git-common-dir"
        )
        if not main or os.path.realpath(main[0]) != os.path.realpath(repo):
            return False
        common = os.path.realpath(os.path.join(repo, main[2]))
        if os.path.realpath(main[1]) != common:
            return False  # `<repo>` is itself a linked worktree, not a main checkout
        if not os.path.lexists(root):
            return True  # where `git worktree add` will create it
        if os.path.islink(root) or not os.path.isdir(root):
            return False
        wt = self._rev_parse(root, "--show-toplevel", "--absolute-git-dir")
        if not wt or os.path.realpath(wt[0]) != os.path.realpath(root):
            return False
        gdir = os.path.realpath(wt[1])
        if os.path.dirname(gdir) != os.path.join(common, "worktrees"):
            return False
        try:
            back = Path(gdir, "gitdir").read_text(encoding="utf-8").strip()
        except OSError:
            return False
        return os.path.realpath(os.path.join(gdir, back)) == os.path.realpath(
            os.path.join(root, ".git")
        )  # `worktree.useRelativePaths` writes it relative to the registry entry

    def area(self, path: str) -> str:
        """The shared place `path` is in, named for the denial."""
        for p in (os.path.normpath(path), os.path.realpath(path)):
            if self.home not in ("", "/") and _under(p, os.path.normpath(self.home)):
                return f"$HOME ({self.home})"
            for top in _NAMED:
                if _under(p, top):
                    return top
            if _under(p, "/tmp") or _under(p, "/var/tmp"):
                return "the shared /tmp"
        return "outside your worktree and your scratch"


# ── Paths a command writes ─────────────────────────────────────────────────────────────────────


def _resolve(
    word: str, cwd: str | None, values: dict[str, str], home: str
) -> str | None:
    """`word` as the absolute path the shell writes, or None when it cannot be known here.

    Not normalised: `link/..` climbs from the link's target, so `..` is left for `realpath`."""
    w = _ALTERNATE.sub(lambda m: _alternate(m, values), word)
    w = _OPERATOR.sub(lambda m: values.get(m.group(1), m.group(0)), expand(w, values))
    w = _tilde(w, home)
    w = _UNKNOWN.sub(_PLACEHOLDER, w)
    if not w or w.startswith(_PLACEHOLDER):
        return None  # computed at run time: a stated blind spot
    if not w.startswith("/"):
        if cwd is None:
            return None
        w = os.path.join(cwd, w)
    # An unknown segment is one name: it cannot climb, and what follows a literal root stays there.
    return w.replace(_PLACEHOLDER, "_")


_ALTERNATE = re.compile(r"\$\{([A-Za-z_]\w*)(:?)\+([^}]*)\}")
# `${X%…}`, `${X#…}`, `${X:0}`, `${X/…}`: a known X stands for its value, the operator aside (it
# trims or edits; the place a path names is in the value).
_OPERATOR = re.compile(r"\$\{([A-Za-z_]\w*)[%#:/^,][^}]*\}")
_GLOB = re.compile(r"[*?\[]")


def _alternate(m: re.Match[str], values: dict[str, str]) -> str:
    """`${X:+word}`: the word when X is set (and not empty, with the colon), else nothing."""
    name, colon, word = m.groups()
    if name not in values:
        return m.group(0)  # unknown: left for the placeholder
    return word if (values[name] or not colon) else ""


def _tilde(w: str, home: str) -> str:
    """`~` and `~user` at the start of a word, as the shell expands them."""
    m = re.match(r"^~([A-Za-z_][\w.-]*)?(?=/|$)", w)
    if not m:
        return w
    if not m.group(1):
        return home + w[1:]
    try:
        return pwd.getpwnam(m.group(1)).pw_dir + w[m.end() :]
    except KeyError:
        return w  # no such user: the shell leaves the word as written


def _globbed(path: str) -> list[str]:
    """`path`, and each existing path a glob in it matches (`doc?/x` reaches the link `docs`)."""
    if not _GLOB.search(path):
        return [path]
    head, tail = path, ""
    while _GLOB.search(head):
        head, last = os.path.split(head)
        tail = os.path.join(last, tail) if tail else last
    parts = tail.split("/")
    found = [path]
    for k in range(len(parts), 0, -1):
        pattern = os.path.join(head, *parts[:k])
        if _GLOB.search(pattern):
            hits = glob.glob(pattern)[:64]
            found += [os.path.join(h, *parts[k:]) for h in hits]
            if hits:
                break
    return found


# Every unquoted `>` is a redirection to the shell, written after a word (`echo hi>/etc/x`) or a
# duplication (`2>&1>/etc/x`) too: `_cmdtext.redirects` reads only those after a space. Not one
# escaped with a backslash (`\>`), nor a comparison inside `[[ … ]]`.
_ANY_REDIRECT = re.compile(r"(?:\{\w+\}|\d+|&)?(>>|>\||>&|<>|>)(?!\()")
_TEST_SPAN = re.compile(r"^\s*(?:!\s*|(?:if|elif|while|until)\s+)?\[\[\s.*?\]\]", re.S)


def _word_end(raw: str, i: int) -> int:
    while i < len(raw) and not raw[i].isspace() and raw[i] not in ";&|()<>":
        if raw[i] in "'\"":
            close = raw.find(raw[i], i + 1)
            i = len(raw) if close < 0 else close + 1
        else:
            i += 2 if raw[i] == "\\" else 1
    return min(i, len(raw))


def _escaped(text: str, i: int) -> bool:
    n = 0
    while i - n - 1 >= 0 and text[i - n - 1] == "\\":
        n += 1
    return n % 2 == 1


def _redirect_writes(masked: str, raw: str) -> list[tuple[str, int]]:
    """(target, offset in the segment) of each output redirection."""
    out: list[tuple[str, int]] = []
    tests = [m.span() for m in _TEST_SPAN.finditer(masked)]
    for r, start, _e in redirects(masked, raw):
        if any(a <= start < b for a, b in tests):
            continue
        if r.op in _OUTPUT_OPS and r.target and not r.target.startswith("&"):
            out.append((r.target, start))
    for m in _ANY_REDIRECT.finditer(masked):
        if _escaped(masked, m.start()) or any(a <= m.start() < b for a, b in tests):
            continue
        j = m.end()
        if m.group(1) == ">&" and raw[j : j + 1] and raw[j : j + 1] in "0123456789-":
            continue  # `>&2`, `>&-`: a stream, not a file
        while j < len(raw) and raw[j] in " \t":
            j += 1
        word = raw[j : _word_end(raw, j)]
        try:
            target = " ".join(shell_split(word))
        except ValueError:
            target = word
        if target:
            out.append((target, m.start()))
    return out


def _assignments(raw: str) -> dict[str, str]:
    """Literal NAME=value words of a segment that runs no program (`X=/usr`, `export X=/usr`)."""
    try:
        words = shell_split(raw)
    except ValueError:
        words = raw.split()
    found = (re.match(r"^([A-Za-z_]\w*)=(.*)$", w, re.S) for w in words)
    return {m.group(1): m.group(2) for m in found if m}


class _Wrap(NamedTuple):
    short: str  # short options that take a value
    long: frozenset[str]  # long options that take a value
    skip: int  # positionals before the command (chrt's priority, flock's lock file)
    writes: str  # short options whose value is a file it writes (strace -o)
    body: str  # short option whose value is a command string (flock -c, runuser -c)


def _w(
    short: str = "", long: str = "", skip: int = 0, writes: str = "", body: str = ""
) -> _Wrap:
    return _Wrap(short, frozenset(long.split()), skip, writes, body)


# Programs that run the command after their own options, which `_cmdtext` does not set aside.
_EXTRA_WRAPPERS = {
    "setsid": _w(), "fakeroot": _w("ils", "--faked --lib --save-file --load-file"),
    "pkexec": _w("", "--user"), "firejail": _w(), "coproc": _w(), "busybox": _w(),
    "unshare": _w("S", "--setuid --setgid --propagation --root --wd --map-user --map-group"
                       " --map-users --map-groups --kill-child"),
    "runuser": _w("ugGsw", "--user --group --supp-group --shell --whitelist-environment"
                           " --command --session-command", body="c"),
    "ionice": _w("cnpPu", "--class --classdata --pid --pgid --uid"),
    "chrt": _w("T", "--sched-runtime --sched-period --sched-deadline", skip=1),
    "taskset": _w("", "", skip=1), "chroot": _w("", "--userspec --groups", skip=1),
    "flock": _w("wE", "--timeout --conflict-exit-code --command", skip=1, body="c"),
    "watch": _w("nd", "--interval --differences"),
    "nsenter": _w("tSGwr", "--target --setuid --setgid --wd --root --wdns"),
    "systemd-run": _w("puEM", "--unit --property --description --slice --uid --gid --setenv"
                              " --working-directory --machine"),
    "proot": _w("rbw", "--rootfs --bind --pwd"),
    "strace": _w("oeEpsSuPaIXb", "--output --expr --signal --trace --user", writes="o"),
    "ltrace": _w("oeEpsuaAnlL", "--output", writes="o"),
}  # fmt: skip
_MAX_UNWRAP = 4


def _unwrapped(argv: tuple[str, ...]) -> tuple[list[str], list[str], list[str]]:
    """(the command an extra wrapper runs, files the wrapper writes, command strings it runs)."""
    base = os.path.basename(argv[0])
    spec = _EXTRA_WRAPPERS[base]
    rest, i = list(argv), 1
    writes: list[str] = []
    bodies: list[str] = []
    positionals: list[str] = []
    while i < len(rest):
        w = rest[i]
        if w == "--":
            i += 1
            break
        if w.startswith("--"):
            name, eq, val = w.partition("=")
            takes = name in spec.long and not eq
            val = rest[i + 1] if takes and i + 1 < len(rest) else val
            if name in ("--command", "--session-command"):
                bodies.append(val)
            if name == "--output":
                writes.append(val)
            i += 2 if takes else 1
            continue
        if w.startswith("-") and len(w) > 1 and base != "busybox":
            i += 1
            for k, ch in enumerate(w[1:], 1):
                if (
                    ch in spec.short
                    or ch in spec.writes
                    or ch == spec.body
                    or ch == "c"
                    and spec.body
                ):
                    val = w[k + 1 :]
                    if not val and i < len(rest):
                        val, i = rest[i], i + 1
                    if ch in spec.writes:
                        writes.append(val)
                    if spec.body and ch == spec.body:
                        bodies.append(val)
                    break
            continue
        if (
            base == "runuser"
            and not positionals
            and "-u" not in rest
            and "--user" not in rest
        ):
            positionals.append(w)  # `runuser [-l] USER -c CMD`
            i += 1
            continue
        if len(positionals) < spec.skip:
            positionals.append(w)
            i += 1
            continue
        break
    if base == "flock":
        writes += positionals[:1]
    if base == "busybox" and i < len(rest) and rest[i] == "busybox":
        i += 1
    if base == "watch":
        return (
            [],
            writes,
            [*bodies, " ".join(rest[i:])],
        )  # watch runs its words with `sh -c`
    return rest[i:], writes, bodies


_SKIPPED_WRAPPERS = {"timeout", "nice", "nohup", "command", "time", "stdbuf", "exec", "builtin",
                     "doas", "caffeinate", "xargs"}  # fmt: skip
_CWD_WRAPPERS = {
    # program: (its option that sets the directory, short options with a value, long ones)
    "env": ("C", "uSC", {"--unset", "--split-string", "--chdir"}),
    "sudo": ("D", "ughprtUCDTR", {"--user", "--group", "--host", "--prompt", "--role", "--type",
                                  "--other-user", "--close-from", "--command-timeout",
                                  "--chroot", "--chdir"}),
}  # fmt: skip


def _wrapper_cwd(
    raw: str, cwd: str | None, values: dict[str, str], home: str
) -> tuple[str | None, list[str]]:
    """The directory `env -C <dir>` or `sudo -D <dir>` runs its command in, through other
    wrappers before them (`timeout 5 env -C …`) and option clusters (`env -iC …`); and the
    command they run, read past every option (`_cmdtext` stops at `sudo --user root`)."""
    try:
        words = _without_redirections(shell_split(raw))
    except ValueError:
        return cwd, []
    i = 0
    while i < len(words):
        w = words[i]
        base = os.path.basename(w)
        if re.match(r"^[A-Za-z_]\w*=", w):
            i += 1
        elif base in _SKIPPED_WRAPPERS:
            i += 1
            while i < len(words) and words[i].startswith("-"):
                i += (
                    2
                    if words[i] in ("-n", "-s", "-k", "-o", "-e", "-i", "-I", "-u")
                    else 1
                )
            if base == "timeout" and i < len(words):
                i += 1  # the duration
        elif base in _CWD_WRAPPERS:
            flag, short, long_ = _CWD_WRAPPERS[base]
            i += 1
            while i < len(words) and (words[i].startswith("-") or "=" in words[i]):
                w = words[i]
                i += 1
                if w == "--":
                    break
                if w.startswith("--"):
                    name, eq, val = w.partition("=")
                    name = canon(name, long_)
                    takes = name in long_ and not eq
                    if takes and i < len(words):
                        val, i = words[i], i + 1
                    if name == "--chdir":
                        cwd = _resolve(val, cwd, values, home)
                    continue
                if not w.startswith("-"):
                    continue  # env's NAME=value
                for k, ch in enumerate(w[1:], 1):
                    if ch in short:
                        val = w[k + 1 :]
                        if not val and i < len(words):
                            val, i = words[i], i + 1
                        if ch == flag:
                            cwd = _resolve(val, cwd, values, home)
                        break
        else:
            break
    return cwd, words[i:]


_REDIRECT_WORD = re.compile(
    r"^(?:\{\w+\}|\d+|&)?(?:>>|>\||>&|<>|>|<|<&|&>|&>>)(.*)$", re.S
)


def _without_redirections(words: list[str]) -> list[str]:
    """`words` with each redirection (an operator word and its target) taken out."""
    out: list[str] = []
    i = 0
    while i < len(words):
        m = _REDIRECT_WORD.match(words[i])
        if m:
            i += 1 if m.group(1) else 2
            continue
        out.append(words[i])
        i += 1
    return out


_CASE_PATTERN = re.compile(r"^\s*(?:case\s+\S+\s+in\s+)?\(?[^\s()]*\)")


def _subshells(masked: str, in_case: bool) -> tuple[int, list[int]]:
    r"""(the `(`s that open a subshell at the start of a segment, the offsets of the `)`s in it that
    close one opened before). Inside a `case`, the `)` ending a pattern closes nothing; nor does an
    escaped `\)`."""
    lead = len(masked) - len(masked.lstrip(" \t\n("))
    opens = masked[:lead].count("(")
    pattern = (
        _CASE_PATTERN.match(masked[lead:]) if in_case or "case" in masked else None
    )
    skip = lead + pattern.end() - 1 if pattern else -1
    closes: list[int] = []
    depth = 0
    for k in range(lead, len(masked)):
        if k == skip or _escaped(masked, k):
            continue
        if masked[k] == "(":
            depth += 1
        elif masked[k] == ")":
            if depth:
                depth -= 1
            else:
                closes.append(k)
    return opens, closes


def _write_problem(path: str, where: Where) -> str:
    return (
        f"writes {os.path.realpath(path)} ({where.area(path)}). Write only inside your worktree "
        f"and your scratch ({where.scratch_hint()}/<ISSUE-KEY>-<role>/); a stand-in tool goes in "
        "your scratch and on PATH for that one command (`PATH=<scratch>/bin:$PATH make ...`)."
    )


def _write_problems(
    cmd: str, where: Where, start: str | None = None, depth: int = 0
) -> list[str]:
    """Each write outside the allowed places in `cmd`. The outer text's `cd`s move where its later
    commands write, and a `( … )` subshell's end undoes its own (a `case` pattern's `)` closes
    nothing); a text the shell runs from inside another (`$(…)`, `bash -c`) is judged from each
    directory the outer text visits, and its own `cd`s stay inside it."""
    scs = simple_commands(cmd)
    k = 0
    cwd: str | None = where.cwd if depth == 0 else start
    known: dict[str, str] = {}
    problems: list[str] = []
    texts = executable_texts(cmd)
    outer_cwds: list[str | None] = [cwd]
    for t, text in enumerate(texts):
        starts = [cwd] if t == 0 else list(dict.fromkeys(outer_cwds))[:8]
        k_text, known_text = k, known
        for start_cwd in starts:
            # A nested text (`$(…)`, `bash -c`) runs wherever the outer text was when it ran:
            # judged from each directory the outer text visits, its own `cd`s kept inside it.
            got, k, known = _text_problems(text, scs, k_text, known_text, start_cwd, where,
                                           depth, outer_cwds if t == 0 else None)  # fmt: skip
            problems += got
    return problems


def _text_problems(
    text: str,
    scs: list[SimpleCommand],
    k0: int,
    known0: dict[str, str],
    cwd: str | None,
    where: Where,
    depth: int,
    visited: list[str | None] | None,
) -> tuple[list[str], int, dict[str, str]]:
    """The writes of one executable text, from `cwd`; the next unread simple command and the
    variables known after it. `visited` collects each directory the text moves to."""
    problems: list[str] = []
    k, known = k0, dict(known0)
    stack: list[str | None] = []
    in_case = 0
    for masked, raw in segments(text):
        if not masked.strip():
            continue
        sc = None
        if k < len(scs) and scs[k].raw == raw:
            sc, k = scs[k], k + 1
            known = {**known, **dict(sc.env)}
        else:
            known = {**known, **_assignments(raw)}
        values = {"HOME": where.home, **known}
        if cwd is not None:
            values.setdefault("PWD", cwd)
        opens, closes = _subshells(masked, in_case > 0)
        in_case += len(re.findall(r"(?:^|\s|\()case\s", masked))
        in_case -= len(re.findall(r"(?:^|\s)esac\b", masked))
        stack += [cwd] * opens
        # A redirection after a subshell's `)` belongs to the shell outside it.
        after = stack[-len(closes)] if closes and len(stack) >= len(closes) else cwd
        targets = [
            (w, after if closes and at > closes[0] else cwd)
            for w, at in _redirect_writes(masked, raw)
        ]
        if sc is not None:
            problems += _command_problems(sc, cwd, values, where, depth, targets)
            if os.path.basename(sc.argv[0]) in ("cd", "pushd", "popd"):
                cwd = _cd(sc, cwd, values, where.home)
                if visited is not None:
                    visited.append(cwd)
        for word, at_cwd in targets:
            path = _resolve(word, at_cwd, values, where.home)
            for p in _globbed(path) if path is not None else []:
                if not where.allowed(p):
                    problems.append(_write_problem(p, where))
                    break
        for _c in closes:
            cwd = stack.pop() if stack else cwd
            if visited is not None:
                visited.append(cwd)
    return problems, k, known


def _command_problems(
    sc: SimpleCommand,
    cwd: str | None,
    values: dict[str, str],
    where: Where,
    depth: int,
    targets: list[tuple[str, str | None]],
) -> list[str]:
    """Add what `sc`'s program writes to `targets`; judge what a wrapper or `env -C` runs."""
    problems: list[str] = []
    run_cwd, words = _wrapper_cwd(sc.raw, cwd, values, where.home)
    targets += [(w, run_cwd) for w in argv_writes(sc)]
    if (
        words
        and sc.argv
        and words[0] != sc.argv[0]
        and os.path.basename(words[0]) != "env"
    ):
        # `env -iC /usr touch x`, `sudo --user root touch x`: the program `_cmdtext` missed
        real = SimpleCommand(sc.env, tuple(expand(w, values) for w in words), sc.raw)
        targets += [(w, run_cwd) for w in argv_writes(real)]
        problems += docker_problems(real)
    if run_cwd != cwd:
        for body in argv_bodies(sc):  # `env -C /usr sh -c '…'`: the body runs there
            problems += _write_problems(body, where, run_cwd, depth + 1)
    if os.path.basename(sc.argv[0]) not in _EXTRA_WRAPPERS:
        return problems
    if depth >= _MAX_UNWRAP:
        return [
            f"nests wrappers more than {_MAX_UNWRAP} deep, deeper than this hook reads"
        ]
    inner, writes, bodies = _unwrapped(sc.argv)
    targets += [(w, run_cwd) for w in writes]
    texts = [*bodies, " ".join(shlex.quote(w) for w in inner)] if inner else bodies
    for text in texts:
        problems += _write_problems(text, where, run_cwd, depth + 1)
        problems += [p for s in simple_commands(text) for p in docker_problems(s)]
    return problems


def _cd(
    sc: SimpleCommand, cwd: str | None, values: dict[str, str], home: str
) -> str | None:
    if os.path.basename(sc.argv[0]) == "popd":
        return None
    ops = [w for w in sc.argv[1:] if w not in ("-L", "-P", "-e", "-@", "--")]
    if not ops:
        return home
    if ops[0] == "-":
        return None
    return _resolve(ops[0], cwd, values, home)


# ── docker names, tags and ports ───────────────────────────────────────────────────────────────


# ── The call ───────────────────────────────────────────────────────────────────────────────────


def problems(ev: dict[str, object]) -> list[str]:
    tool = ev.get("tool_name")
    ti = tool_input(ev)
    where = Where(ev)
    if tool in _EDIT_FIELD:
        target = text_field(ti, _EDIT_FIELD[tool])
        if not target:
            return []
        path = os.path.join(where.cwd, _tilde(target, where.home))
        if where.allowed(path):
            return []
        return [
            f"writes {path} ({where.area(path)}). Write only inside your worktree and your "
            f"scratch ({where.scratch_hint()}/<ISSUE-KEY>-<role>/)."
        ]
    if tool != "Bash":
        return []
    cmd = text_field(ti, "command")
    set_unit(where.cwd, os.environ.get("CLAUDE_PROJECT_DIR", ""))
    out = _write_problems(cmd, where)
    for sc in simple_commands(cmd):
        out += docker_problems(sc)
    return list(dict.fromkeys(out))


def main() -> int:
    found = problems(load_event())
    if not found:
        return 0
    print(
        "DENIED: this leaves state on the shared machine that is not yours alone.\n"
        + "\n".join(f"  - {p}" for p in found)
        + '\nSee --doc FLEET-AGENT-CONDUCT-STANDARD, "Shared machine". A run whose names, ports '
        "and paths an emitted make block owns runs through make.",
        file=sys.stderr,
    )
    return 2


sys.exit(guarded(main, "shared-machine"))
